entries[115294] = { ["name"] = "Manatee", ["text"] = "Kanalisiert (Wirken in 3 sek.)\nVerbraucht 1 Stapel 'Manatee' pro 0.5 Sek., um 44625 Mana wiederherzustellen. Verringert die Manakosten Eurer Zauber pro verbrauchtem Stapel 'Manatee' für 1.00 Sek. um 30%.\n\nKann aus der Bewegung heraus gewirkt werden, aber die Bewegungsgeschwindigkeit ist beim Kanalisieren um 40% verringert." }
